INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019s-am-31','exam-sg','個人情報保護・JIS Q 15001','standard','single_choice','【平成31年度 春期 午前 問31】JIS Q 15001:2017（個人情報保護マネジメントシステム－要求事項）に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"開示対象個人情報は保有個人データとは別に定義され，保有期間によらず全ての個人情報が該当する"},{"id":"b","text":"規格文書の構成はJIS Q 27001:2014と異なり，マネジメントシステム規格に共通的な章立てが採用されていない"},{"id":"c","text":"特定の機微な個人情報が定義され，労働組合への加盟といった情報が例として挙げられている"},{"id":"d","text":"本人から書面に記載された個人情報を直接取得する場合，利用目的などをあらかじめ書面で本人に明示し，同意を得なければならない"}]','"d"','本人から書面で個人情報を直接取得するときは，利用目的などを事前に明示し，同意を得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-32','exam-sg','政府機関の情報セキュリティ基準','standard','single_choice','【平成31年度 春期 午前 問32】「政府機関等の情報セキュリティ対策のための統一基準（平成30年度版）」に関する説明として，適切なものはどれか。','[{"id":"a","text":"機密性，完全性及び可用性それぞれの観点による情報の格付の区分を定義している"},{"id":"b","text":"個人情報保護法に基づいて制定されたものである"},{"id":"c","text":"適用範囲は全ての政府機関及び全ての民間企業としている"},{"id":"d","text":"不正アクセス禁止法に基づいて制定されたものである"}]','"a"','統一基準は情報の機密性・完全性・可用性の観点で格付区分を定義する。適用対象は政府機関等であり全民間企業ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-33','exam-sg','迷惑メール対策・特定電子メール法','standard','single_choice','【平成31年度 春期 午前 問33】企業が「特定電子メールの送信の適正化等に関する法律」における特定電子メールに該当する広告宣伝メールを送信する場合に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"SMSで送信する場合はオプトアウト方式を利用する"},{"id":"b","text":"オプトイン方式，オプトアウト方式のいずれかを選択する"},{"id":"c","text":"原則としてオプトアウト方式を利用する"},{"id":"d","text":"原則としてオプトイン方式を利用する"}]','"d"','広告宣伝目的の特定電子メールは，原則として事前同意を得た相手に送るオプトイン方式が必要。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-34','exam-sg','個人番号・特定個人情報','standard','single_choice','【平成31年度 春期 午前 問34】個人情報保護委員会「特定個人情報の適正な取扱いに関するガイドライン（事業者編）」及びそのQ&Aによれば，事業者によるファイル作成が禁止されている場合はどれか。','[{"id":"a","text":"システム障害に備えた特定個人情報ファイルのバックアップファイルを作成する"},{"id":"b","text":"従業員の個人番号を利用して業務成績を管理するファイルを作成する"},{"id":"c","text":"税務署に提出する資料間の整合性を確認するために個人番号を記載したチェック用ファイルを作成する"},{"id":"d","text":"保険契約者の死亡保険金支払に伴う支払調書ファイルを作成する"}]','"b"','個人番号は法令で定められた社会保障・税・災害対策等の事務に限って利用でき，業務成績管理目的のファイル作成は禁止。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-35','exam-sg','著作権・著作者人格権','standard','single_choice','【平成31年度 春期 午前 問35】著作者人格権に該当するものはどれか。','[{"id":"a","text":"印刷，撮影，複写などの方法によって著作物を複製する権利"},{"id":"b","text":"公衆からの要求に応じて自動的にサーバから情報を送信する権利"},{"id":"c","text":"著作物の複製物を公衆に貸し出す権利"},{"id":"d","text":"自らの意思に反して著作物を変更，切除されない権利"}]','"d"','著作者人格権には公表権・氏名表示権・同一性保持権があり，意に反する改変を拒むのは同一性保持権。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-37','exam-sg','システム監査・外観上の独立性','standard','single_choice','【平成31年度 春期 午前 問37】経営者が社内のシステム監査人の外観上の独立性を担保するために講じる措置として，最も適切なものはどれか。','[{"id":"a","text":"システム監査人にITに関する継続的学習を義務付ける"},{"id":"b","text":"システム監査人に必要な知識や経験を定めて公表する"},{"id":"c","text":"システム監査人の監査技法研修制度を設ける"},{"id":"d","text":"システム監査人の所属部署を内部監査部門とする"}]','"d"','外観上の独立性を確保するには，監査対象部門から独立した内部監査部門に所属させることが有効。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-38','exam-sg','セキュア開発・監査指摘','standard','single_choice','【平成31年度 春期 午前 問38】ソフトウェア開発プロセスにおけるセキュリティを確保する取組について，JIS Q 27001:2014附属書Aの管理策に照らして監査した。監査報告書に指摘事項として記載すべき状況はどれか。','[{"id":"a","text":"ソフトウェア開発におけるセキュリティ機能の試験は，開発期間が終了した後に実施している"},{"id":"b","text":"ソフトウェア開発は，セキュリティ確保に配慮した開発環境において行っている"},{"id":"c","text":"開発を外部委託している場合，委託先の監督・監視でセキュリティ確保の観点を考慮している"},{"id":"d","text":"パッケージソフトウェアの変更は，セキュリティ確保の観点から必要な変更に限定している"}]','"a"','セキュリティ機能の試験は開発期間中に実施すべきであり，終了後だけの試験は不備となる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-39','exam-sg','システム監査報告書・指摘事項','standard','single_choice','【平成31年度 春期 午前 問39】システム監査報告書に記載する指摘事項に関する説明のうち，適切なものはどれか。','[{"id":"a","text":"監査証拠による裏付けの有無にかかわらず，監査人が必要と判断した事項を記載する"},{"id":"b","text":"監査人が必要と判断した事項のうち，監査対象部門の責任者が承認した事項を記載する"},{"id":"c","text":"調査結果に事実誤認がないことを監査対象部門に確認した上で，監査人が必要と判断した事項を記載する"},{"id":"d","text":"不備の内容や重要性は考慮せず，全てを漏れなく指摘事項として記載する"}]','"c"','指摘事項は監査証拠に基づき，監査対象部門に事実誤認がないことを確認した上で記載する。部門責任者の承認が条件ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-40','exam-sg','情報セキュリティ監査・保証型と助言型','standard','single_choice','【平成31年度 春期 午前 問40】経済産業省「情報セキュリティ監査基準 実施基準ガイドライン（Ver1.0）」における保証型監査と助言型監査の実施に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"同じ監査対象では，保証型から始め，保証が得られた後に助言型へ切り替えなければならない"},{"id":"b","text":"保証型監査と助言型監査は排他的であり，監査人はどちらか一方を選ばなければならない"},{"id":"c","text":"保証型か助言型かは監査要請者のニーズではなく，監査人の責任で決定する"},{"id":"d","text":"不特定多数の利害関係者の情報を扱う情報システムには，保証型監査を定期的に実施し，結果を開示することが有用である"}]','"d"','多くの利害関係者の情報を扱うシステムでは，保証型監査の結果を開示することで対策の適切性を示せる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja');
